CREATE TABLE t3(c0,c1,c2,c3,c4,c5,c6,c7,c8,c9,c10,c11,c12,c13,c14,c15,c16,c17,c18,c19,c20,c21,c22,c23,c24,c25,c26,c27,c28,c29,c30,c31,c32,c33,c34,c35,c36,c37,c38,c39,c40,c41,c42,c43,c44,c45,c46,c47,c48,c49,c50,c51,c52,c53,c54,c55,c56,c57,c58,c59,c60,c61,c62,c63,c64,c65);CREATE TABLE t3_changes(colnum,oldval,newval);INSERT INTO t3(c43) VALUES('a43');WITH RECURSIVE n(v) AS (VALUES(0) UNION ALL SELECT v+1 FROM n WHERE v<42) INSERT INTO t3_changes SELECT v,'a'||v,'b'||v FROM n;CREATE TRIGGER t3c43 AFTER UPDATE ON t3 WHEN old.c43!=new.c43 BEGIN INSERT INTO t3_changes VALUES(43,old.c43,new.c43);END;CREATE TRIGGER z AFTER UPDATE ON t3 WHEN old.c65 IS NOT new.c65 BEGIN SELECT 1;END;